static int fee(int amount, boolean isAgent) {
    int fee = 0;
    if (amount <= 0) return -1;
    if (amount > 25000) {
        fee = 250;
    } else {
        fee = amount * 185 / 10000;   // 1.85%, integer division
    }
    if (isAgent && fee > 0) {
        fee = fee / 2;
    }
    return fee;
}
